"""
Batch trend-preserving denoiser.

The returned sample at output i estimates input i + window_size - 1.
"""
import numpy as np


def adaptive_filter(x, window_size=20):
    x = np.asarray(x, dtype=float).reshape(-1)
    if x.size < window_size:
        raise ValueError("Input signal length must be >= window_size")
    return np.convolve(x, np.ones(window_size) / float(window_size), mode="valid")


def _robust_scale(a):
    a = np.asarray(a, dtype=float).reshape(-1)
    if a.size == 0:
        return 0.0
    m = np.median(a)
    return float(1.4826 * np.median(np.abs(a - m)))


def _filled_signs(y):
    s = np.sign(np.diff(y)).astype(float)
    if s.size == 0:
        return s
    for i in range(1, s.size):
        if s[i] == 0:
            s[i] = s[i - 1]
    for i in range(s.size - 2, -1, -1):
        if s[i] == 0:
            s[i] = s[i + 1]
    return s


def _fallback(x, window_size):
    n = len(x)
    if n < 5:
        return x.copy()
    k = min(max(5, 2 * (window_size // 2) + 1), n if n % 2 else n - 1)
    try:
        from scipy.signal import savgol_filter
        return np.asarray(savgol_filter(x, k, min(3, k - 1), mode="interp"))
    except Exception:
        p = np.pad(x, (k // 2, k // 2), mode="edge")
        return np.convolve(p, np.ones(k) / k, mode="valid")[:n]


def _curvature_trend(x, sigma):
    """Second-order L1 trend estimate; step-adjacent curvature is unpenalized."""
    x = np.asarray(x, dtype=float)
    n = x.size
    if n < 5:
        return x.copy()
    try:
        from scipy import sparse
        from scipy.sparse.linalg import spsolve

        spread = float(np.percentile(x, 75) - np.percentile(x, 25))
        jump_size = max(5.0 * sigma, 0.18 * spread, 1e-8)
        jumps = np.flatnonzero(np.abs(np.diff(x)) >= jump_size) + 1

        d2n = n - 2
        D = sparse.diags(
            (np.ones(d2n), -2.0 * np.ones(d2n), np.ones(d2n)),
            (0, 1, 2), shape=(d2n, n), format="csr"
        )
        keep = np.ones(d2n)
        for j in jumps:
            keep[max(0, j - 1):min(d2n, j + 1)] = 0.0
        D = sparse.diags(keep) @ D

        weights = np.ones(n)
        for j in jumps:
            weights[max(0, j - 1):min(n, j + 1)] = 4.0

        lam = max(0.55 * sigma * np.sqrt(float(n)), 1e-8)
        rho = max(1.0, 2.0 * lam / (sigma * sigma + 1e-8))
        A = sparse.diags(weights) + rho * (D.T @ D)

        y = x.copy()
        z = np.asarray(D @ y).reshape(-1)
        u = np.zeros(d2n)
        for _ in range(60):
            old_y = y
            y = np.asarray(spsolve(A, weights * x + rho * D.T @ (z - u))).reshape(-1)
            v = np.asarray(D @ y).reshape(-1) + u
            z = np.sign(v) * np.maximum(np.abs(v) - lam / rho, 0.0)
            u += np.asarray(D @ y).reshape(-1) - z
            primal = np.linalg.norm(np.asarray(D @ y).reshape(-1) - z)
            dual = rho * np.linalg.norm(D.T @ (z - np.asarray(D @ old_y).reshape(-1)))
            if primal / (1.0 + np.linalg.norm(y)) < 1e-4 and dual / (1.0 + np.linalg.norm(y)) < 1e-4:
                break
        return y if np.all(np.isfinite(y)) else x.copy()
    except Exception:
        return _fallback(x, 11)


def _cancel_weak_excursions(y, raw, sigma):
    """Endpoint-preserving removal of raw-unsupported small oscillations."""
    y = np.asarray(y, dtype=float).copy()
    raw = np.asarray(raw, dtype=float)
    if y.size < 7:
        return y

    residual = _robust_scale(raw - y)
    slope = _robust_scale(np.diff(y))
    tau = max(0.35 * residual, 0.08 * slope, 1e-12)
    spread = float(np.percentile(raw, 75) - np.percentile(raw, 25))
    jump = max(5.0 * sigma, 0.18 * spread, 6.0 * tau, 1e-12)

    for _ in range(2):
        signs = _filled_signs(y)
        ext = np.flatnonzero(signs[1:] != signs[:-1]) + 1
        if ext.size < 3:
            break
        changed = False
        for q in range(1, ext.size - 1):
            left, mid, right = map(int, ext[q - 1:q + 2])
            if right - left < 2:
                continue
            prominence = min(abs(y[mid] - y[left]), abs(y[right] - y[mid]))
            raw_prom = min(abs(raw[mid] - raw[left]), abs(raw[right] - raw[mid]))
            has_jump = np.any(np.abs(np.diff(raw[left:right + 1])) >= jump)
            if prominence < 1.25 * tau and raw_prom < 2.0 * tau and not has_jump:
                y[left:right + 1] = np.linspace(y[left], y[right], right - left + 1)
                changed = True
        if not changed:
            break
    return y


def enhanced_filter_with_trend_preservation(x, window_size=20):
    x = np.asarray(x, dtype=float).reshape(-1)
    if x.size < window_size:
        raise ValueError("Input signal length must be >= window_size")

    if not np.all(np.isfinite(x)):
        finite = x[np.isfinite(x)]
        fill = float(np.median(finite)) if finite.size else 0.0
        x = np.nan_to_num(x, nan=fill, posinf=fill, neginf=fill)

    if x.size < 7:
        return _fallback(x, window_size)[window_size - 1:]

    sigma = max(_robust_scale(np.diff(x)) / np.sqrt(2.0), 1e-12)
    y = _curvature_trend(x, sigma)
    y = _cancel_weak_excursions(y, x, sigma)
    return np.asarray(y, dtype=float)[window_size - 1:]


def process_signal(input_signal, window_size=20, algorithm_type="enhanced"):
    if algorithm_type == "enhanced":
        return enhanced_filter_with_trend_preservation(input_signal, window_size)
    return adaptive_filter(input_signal, window_size)


def generate_test_signal(length=1000, noise_level=0.3, seed=42):
    rng = np.random.RandomState(seed)
    t = np.linspace(0, 10, length)
    clean = (
        2 * np.sin(2 * np.pi * 0.5 * t)
        + 1.5 * np.sin(2 * np.pi * 2 * t)
        + 0.5 * np.sin(2 * np.pi * 5 * t)
        + 0.8 * np.exp(-t / 5) * np.sin(2 * np.pi * 1.5 * t)
    )
    clean += 0.1 * t * np.sin(0.2 * t)
    clean += np.cumsum(rng.randn(length) * 0.05)
    return clean + rng.normal(0, noise_level, length), clean


def run_signal_processing(noisy_signal=None, signal_length=1000,
                          noise_level=0.3, window_size=20):
    if noisy_signal is None:
        noisy_signal, clean_signal = generate_test_signal(
            signal_length, noise_level
        )
    else:
        noisy_signal = np.asarray(noisy_signal, dtype=float)
        clean_signal = None

    filtered = process_signal(noisy_signal, window_size, "enhanced")
    if clean_signal is None:
        return {
            "filtered_signal": filtered,
            "clean_signal": None,
            "noisy_signal": None,
            "correlation": 0,
            "noise_reduction": 0,
            "signal_length": len(filtered),
        }

    clean = clean_signal[window_size - 1:]
    noisy = noisy_signal[window_size - 1:]
    m = min(len(filtered), len(clean))
    filtered, clean, noisy = filtered[:m], clean[:m], noisy[:m]
    corr = (
        float(np.corrcoef(filtered, clean)[0, 1])
        if m > 1 and np.std(filtered) > 0 and np.std(clean) > 0 else 0.0
    )
    before = np.var(noisy - clean)
    after = np.var(filtered - clean)
    reduction = float((before - after) / before) if before > 0 else 0.0
    return {
        "filtered_signal": filtered,
        "clean_signal": clean,
        "noisy_signal": noisy,
        "correlation": corr,
        "noise_reduction": reduction,
        "signal_length": m,
    }


if __name__ == "__main__":
    results = run_signal_processing()
    print("Signal processing completed!")
    print(f"Correlation with clean signal: {results['correlation']:.3f}")
    print(f"Noise reduction: {results['noise_reduction']:.3f}")
    print(f"Processed signal length: {results['signal_length']}")

